package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Dept     string `json:"department"`
	Salary   string `json:"salary,omitempty"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// employeeSearch handles directory lookups with flexible filtering
func employeeSearch(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name")
	dept := r.URL.Query().Get("dept")
	includeSalary := r.Header.Get("X-Include-Compensation") == "true"

	// Build dynamic query based on provided filters
	clauses := []string{"1=1"}
	if name != "" {
		clauses = append(clauses, fmt.Sprintf("e.full_name ILIKE '%%%s%%'", name))
	}
	if dept != "" {
		clauses = append(clauses, fmt.Sprintf("e.department = '%s'", dept))
	}

	columns := "e.id, e.full_name, e.email, e.department"
	if includeSalary {
		columns += ", c.base_salary"
	}

	query := fmt.Sprintf("SELECT %s FROM employees e", columns)
	if includeSalary {
		query += " LEFT JOIN compensation c ON c.employee_id = e.id"
	}
	query += " WHERE " + strings.Join(clauses, " AND ")
	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if includeSalary {
			var salary sql.NullString
			err = rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Dept, &salary)
			if salary.Valid {
				sr.Salary = salary.String
			}
		} else {
			err = rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Dept)
		}
		if err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthCheck endpoint for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

// bulkExport generates CSV for HR - uses parameterized query
func bulkExport(w http.ResponseWriter, r *http.Request) {
	apiKey := r.Header.Get("X-API-Key")
	if apiKey != os.Getenv("EXPORT_API_KEY") {
		http.Error(w, "Forbidden", 403)
		return
	}
	rows, err := db.Query("SELECT id, full_name, email, department FROM employees ORDER BY id")
	if err != nil {
		http.Error(w, "Error", 500)
		return
	}
	defer rows.Close()
	w.Header().Set("Content-Type", "text/csv")
	w.Write([]byte("id,name,email,department\n"))
	for rows.Next() {
		var id int
		var name, email, dept string
		rows.Scan(&id, &name, &email, &dept)
		fmt.Fprintf(w, "%d,%s,%s,%s\n", id, name, email, dept)
	}
}

func main() {
	http.HandleFunc("/api/directory/search", employeeSearch)
	http.HandleFunc("/api/export", bulkExport)
	http.HandleFunc("/health", healthCheck)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
